    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xC8DA9A79BD2A3961ULL + 0x91455C62A6A1BAB4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xC2170715F75E09FBULL + 0xF6B60432A0F791A6ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xE085CDE280243E91ULL + 0xB20F212C70B34405ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xB1BB189402E7567FULL + 0xC081A3A18295EFABULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xCB51EC92106391BDULL + 0xBCD9ADB88904D721ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0x80C65F1B919C4F39ULL + 0xE53D78F93DE138DAULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xE5ECD86D5EDFE32DULL + 0xFDFC6FB045E7C44DULL);
