            //
            aOrbiterF = (aWandererI + RotL64(aPrevious, 35U)) + 0x79DB2A20AA290538ULL;
            aOrbiterI = ((aWandererE + RotL64(aCross, 10U)) + 0xDAC0BF05F40D5275ULL) + aOASaltD[(((511U - aIndex) + 461U)) & S_SALT1];
            aOrbiterG = (((aWandererA + RotL64(aScatter, 47U)) + RotL64(aCarry, 43U)) + 0x94988C1724C707C3ULL) + aOASaltG[((aIndex + 39U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aIngress, 37U)) + RotL64(aCarry, 53U)) + 0x6C19A65C70C59D74ULL;
            aOrbiterA = (((aWandererK + RotL64(aScatter, 43U)) + 0xE255768AE253DC68ULL) + aOASaltE[(((511U - aIndex) + 357U)) & S_SALT1]) + aNonceWordK;
            aOrbiterD = ((aWandererB + RotL64(aCross, 3U)) + RotL64(aCarry, 3U)) + 0x2ACADB5F063C1DD8ULL;
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 12U)) + 0x5E2219DAD04D7D22ULL) + aOASaltH[((aIndex + 188U)) & S_SALT1];
            aOrbiterE = ((aWandererJ + RotL64(aIngress, 53U)) + 0x6D0E2F2479C75CCCULL) + aOASaltC[((aIndex + 367U)) & S_SALT1];
