            aOrbiterF = RotL64((aOrbiterF * 0x316E15A1C29582C3ULL), 5U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x71825E25AD25ED84ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x8481B419819E7244ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x0C4AA9F9C29633BDULL), 47U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x050DEDB6E4245953ULL) + aOUSaltC[(((511U - aIndex) + 90U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xF1AABD67C896CB5AULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA9834A9F7DB08C95ULL), 3U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x022D52F4E684D0B3ULL) + aOUSaltA[(((511U - aIndex) + 237U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xEDD4BD91D01F9CE2ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x692352F77DC7B69BULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0x1B150ABC83FBF547ULL) + aOUSaltH[(((511U - aIndex) + 176U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x902B25EE8206C45BULL;
            aOrbiterK = RotL64((aOrbiterK * 0x655EE2BB160BBE03ULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0xA9021AE654893AC5ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x53D09CC5EE9E03E8ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x973F0A93D5DAFA6FULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x788F380AE5CFA9F0ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xDA3B426B2F77A2ECULL;
            aOrbiterB = RotL64((aOrbiterB * 0x57A49F46167A26E5ULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0xB12141720484D990ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x82B44AA492167BBAULL;
            aOrbiterI = RotL64((aOrbiterI * 0x811A36B55846239BULL), 37U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xD97C11D30A9DE086ULL;
            aOrbiterC = (((aOrbiterC ^ aOrbiterJ) ^ 0xBDFA11DFD8E26A44ULL) ^ aOUSaltB[(((511U - aIndex) + 153U)) & S_SALT1]) ^ aNonceWordG;
            aOrbiterC = RotL64((aOrbiterC * 0xE3B2E3ED03D9A035ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0xEF0B360461643698ULL) + aOUSaltD[(((511U - aIndex) + 83U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0xF65983B144E5A6B8ULL) ^ aNonceWordC;
            aOrbiterA = RotL64((aOrbiterA * 0x176617D1F8E6FE93ULL), 21U);
            //
            aIngress = RotL64(aOrbiterH, 3U) ^ aOrbiterC;
