            aScatter = (RotL64(aCarry, 27U) ^ RotL64(aIngress, 43U)) + (RotL64(aPrevious, 10U) ^ RotL64(aCross, 57U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = ((aWandererH + RotL64(aCross, 30U)) + 0xF64724AE3E117F59ULL) + aOASaltF[((aIndex + 159U)) & S_SALT1];
            aOrbiterI = (aWandererB + RotL64(aPrevious, 37U)) + 0x568F0A8FBE729BC9ULL;
            aOrbiterB = ((aWandererJ + RotL64(aIngress, 43U)) + 0x1AE9E9EE2E5EAFC5ULL) + aOASaltH[(((511U - aIndex) + 147U)) & S_SALT1];
            aOrbiterJ = (((aWandererC + RotL64(aScatter, 53U)) + RotL64(aCarry, 35U)) + 0x5B4D9AF62E244A4EULL) + aOASaltD[(((511U - aIndex) + 42U)) & S_SALT1];
