            aOrbiterH = (aWandererI + RotL64(aIngress, 10U)) + 0xABEC986847BE1AB7ULL;
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 3U)) + RotL64(aCarry, 5U)) + 0x725748B5EB9BCD2AULL;
            aOrbiterK = ((aWandererF + RotL64(aScatter, 23U)) + 0x978BB7E53EB42320ULL) + aOASaltA[((aIndex + 289U)) & S_SALT1];
            aOrbiterF = (aWandererE + RotL64(aCross, 57U)) + 0x5412D12D65C7D80FULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x23D83FB3AF2F9213ULL) + aOUSaltH[((aIndex + 80U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x1077559D765BCAC5ULL;
