            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0xA62160B70C68A8C8ULL) + aOUSaltF[((aIndex + 337U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x7A37EC437135850CULL;
            aOrbiterI = RotL64((aOrbiterI * 0x274A5C19773B8889ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x1170A5B4BB0CDA96ULL) + aOUSaltG[((aIndex + 105U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xB10E4E210D29AE63ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC7762D0D93A7C431ULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x1B4BD8D3D61B4186ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xEBDE14B604C0575DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x24BA1484ED5065C5ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x0A1329C3902E8DB5ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0x375406C0CBEC1BEFULL) ^ aOUSaltC[(((511U - aIndex) + 179U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xF046BA0F9A743ED1ULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x213C97B26A946906ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x7077C04AEBC8543DULL;
            aOrbiterK = RotL64((aOrbiterK * 0x854068D02B432A97ULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xBAAE1E02C55F5E46ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0xFDB83AF9ED3D5476ULL) ^ aOUSaltE[(((511U - aIndex) + 345U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x6C2A5AC703C5E8C1ULL), 19U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x2E66D925AAE434A2ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x0B0273D8AE76F689ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xCC3F3027809C1095ULL), 57U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x26A0A4E19B323F36ULL) + aOUSaltA[((aIndex + 78U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xF01CF0DB8599D747ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB46CD2D6A9B906C9ULL), 41U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 13U);
            aIngress = aIngress + (RotL64(aOrbiterF, 6U) ^ aOrbiterJ);
