            aOrbiterB = (((aWandererK + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0x2CE524B104142A7EULL) + aOASaltD[((aIndex + 328U)) & S_SALT1];
            aOrbiterF = ((aWandererC + RotL64(aScatter, 13U)) + RotL64(aCarry, 39U)) + 0xC841D96226DEA6DCULL;
            aOrbiterA = (aWandererJ + RotL64(aCross, 27U)) + 0x55717C5175AB8F98ULL;
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 50U)) + RotL64(aCarry, 29U)) + 0x82C187C54C43833AULL;
